    attachment: [
        # 這個是chat直接上傳的來源
        {
         "contentName:"",
         "contentType:"",  # MimeType
         "attachmentDataRef: {
              "resourceName":""  # id
            }
        },
        # 這個是從Drive上的來源
        {
         "name":"",
         "driveDataRef": {
             "driveFileId": ""  # id
